package com.smartmart.wishlist.entity;
import com.smartmart.product.entity.Product; import com.smartmart.user.entity.User; import jakarta.persistence.*; import lombok.*; import org.hibernate.annotations.CreationTimestamp; import java.time.LocalDateTime;
@Entity @Table(name="wishlists", uniqueConstraints=@UniqueConstraint(columnNames={"user_id","product_id"})) @Getter @Setter @NoArgsConstructor @AllArgsConstructor @Builder public class Wishlist { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY) private User user; @ManyToOne(fetch=FetchType.LAZY) private Product product; @CreationTimestamp private LocalDateTime createdAt; }
